                    (?:(?<month>[+-]?\d*(?:\.\d+)?)M)?
                    (?:(?<week>[+-]?\d*(?:\.\d+)?)W)?
                    (?:(?<day>[+-]?\d*(?:\.\d+)?)D)?
                    (?:T
                        (?:(?<hour>[+-]?\d*(?:\.\d+)?)H)?
                        (?:(?<minute>[+-]?\d*(?:\.\d+)?)M)?
                        (?:(?<second>[+-]?\d*(?:\.\d+)?)S)?
