$b = serialize($a);
echo "plain: OK\n";

// Issue scenario 2: diff interval
$a = Carbon::now();
$b = Carbon::now()->addDay();
$c = $a->diffAsCarbonInterval($b);
$d = serialize($c);
echo "diff serialize: OK\n";

